function json(res,status,obj,headers={}){res.writeHead(status,{'content-type':'application/json','cache-control':'no-store',...headers});res.end(JSON.stringify(obj));}
function cookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').filter(Boolean).map(v=>v.trim().split('=')));}
const fallbackSessionSecret=crypto.randomBytes(48).toString('hex'),sessionSecret=()=>process.env.SESSION_SECRET||fallbackSessionSecret;
function makeSession(payload){const body=Buffer.from(JSON.stringify({...payload,exp:Date.now()+12*3600e3})).toString('base64url'),sig=crypto.createHmac('sha256',sessionSecret()).update(body).digest('base64url');return body+'.'+sig}
function readSession(raw){try{if(!raw)return null;const [body,sig]=String(raw).split('.');if(!body||!sig)return null;const expected=crypto.createHmac('sha256',sessionSecret()).update(body).digest('base64url'),a=Buffer.from(sig),b=Buffer.from(expected);if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return null;const s=JSON.parse(Buffer.from(body,'base64url').toString());return s.exp>Date.now()?s:null}catch{return null}}
function validTimeZone(tz){try{new Intl.DateTimeFormat('en-US',{timeZone:tz}).format();return true}catch{return false}}
function dateInZone(tz,date=new Date()){const zone=validTimeZone(tz)?tz:'UTC',parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date),get=t=>parts.find(p=>p.type===t)?.value;return get('year')+'-'+get('month')+'-'+get('day')}
function familySession(req,d){const s=readSession(cookies(req).rl_family);if(!s?.family_id)return null;const fam=(d.families||[]).find(v=>v.id===s.family_id);return fam?{...s,family:fam}:null}
function auth(req,d){const s=readSession(cookies(req).rl_session);if(!s)return null;if(s.staff_id){const staff=(d.staff||[]).find(v=>v.id===s.staff_id&&v.status==='active');return staff?{owner:null,staff,role:staff.role||'staff',org:d.organizations.find(o=>o.id===staff.organization_id)}:null}const owner=(d.owners||[]).find(o=>o.id===s.owner_id);return owner?{owner,staff:null,role:'owner',org:d.organizations.find(o=>o.id===owner.organization_id)}:null}
function requireAuth(req,res,d){const a=auth(req,d);if(!a){json(res,401,{error:'Please sign in again.'});return null}return a}function requireRole(req,res,d,roles){const a=requireAuth(req,res,d);if(!a)return null;if(!roles.includes(a.role)){json(res,403,{error:'Your role does not allow this action.'});return null}return a}
