function body(req){return new Promise((resolve,reject)=>{const chunks=[];let size=0,failed=false;const fail=(message,status)=>{if(failed)return;failed=true;reject(Object.assign(new Error(message),{status}))};req.on('data',c=>{size+=c.length;if(size>1024*1024)return fail('Request too large',413);if(!failed)chunks.push(c)});req.on('end',()=>{if(failed)return;try{const text=Buffer.concat(chunks).toString('utf8');resolve(text?JSON.parse(text):{})}catch{fail('Invalid JSON request',400)}});req.on('aborted',()=>fail('Request aborted',400));req.on('error',()=>fail('Request interrupted',400))})}
