async function stripeRequest(pathname,params,{account,idempotencyKey}={}){if(!process.env.STRIPE_SECRET_KEY)throw Object.assign(new Error('Stripe is not configured on this environment.'),{status:503});const headers={Authorization:'Bearer '+process.env.STRIPE_SECRET_KEY,'Content-Type':'application/x-www-form-urlencoded'};if(account)headers['Stripe-Account']=account;if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const r=await fetch('https://api.stripe.com'+pathname,{method:'POST',headers,body:new URLSearchParams(params),signal:AbortSignal.timeout(15000)}),j=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(j.error?.message||'Stripe request failed.'),{status:r.status>=500?503:409,stripe:j.error});return j}
