async function maybeAutoOffer(d,sessionId,organizationId){const sess=(d.sessions||[]).find(v=>v.id===sessionId),prog=sess&&(d.programs||[]).find(v=>v.id===sess.program_id);if(!sess||!prog||prog.waitlist_mode==='manual'||sess.status!=='open'||!databaseStatus.ready)return [];const offered=await database.withTransaction(async client=>{const sr=await client.query('select s.capacity,s.status,p.organization_id,p.waitlist_offer_hours from sessions s join programs p on p.id=s.program_id where s.id=$1 for update of s',[sessionId]);if(!sr.rowCount||sr.rows[0].organization_id!==organizationId||sr.rows[0].status!=='open')return [];const count=await client.query("select (select count(*) from registrations where session_id=$1 and status='enrolled')::int as enrolled,(select count(*) from waitlist where session_id=$1 and status='offered' and (offer_expires_at is null or offer_expires_at>now()))::int as reserved",[sessionId]),slots=Math.max(0,Number(sr.rows[0].capacity)-count.rows[0].enrolled-count.rows[0].reserved);if(!slots)return [];const q=await client.query("select id from waitlist where session_id=$1 and organization_id=$2 and status='waiting' order by created_at asc for update skip locked limit $3",[sessionId,organizationId,slots]),expires=new Date(Date.now()+Number(sr.rows[0].waitlist_offer_hours||24)*3600e3).toISOString(),out=[];for(const row of q.rows){await client.query("update waitlist set status='offered',offer_expires_at=$1 where id=$2",[expires,row.id]);out.push({id:row.id,offer_expires_at:expires})}return out});if(offered.length){d.audit=d.audit||[];for(const o of offered){const w=(d.waitlist||[]).find(v=>v.id===o.id);if(w){w.status='offered';w.offer_expires_at=o.offer_expires_at}d.audit.push({id:id('audit'),organization_id:organizationId,action:'waitlist.auto_offered',detail:o.id,created_at:new Date().toISOString()})}save(d)}return offered}
async function maintainWaitlistOffers(){if(!databaseStatus.ready)return;let expired=[];try{expired=await database.withTransaction(async client=>{const q=await client.query("update waitlist set status='expired' where status='offered' and offer_expires_at is not null and offer_expires_at<=now() returning id,session_id,organization_id");return q.rows})}catch(e){console.error('Waitlist expiry maintenance failed:',e.message);return}if(!expired.length)return;const d=load(),keys=new Map();for(const row of expired){const w=(d.waitlist||[]).find(v=>v.id===row.id);if(w)w.status='expired';d.audit=d.audit||[];d.audit.push({id:id('audit'),organization_id:row.organization_id,action:'waitlist.offer_expired',detail:row.id,created_at:new Date().toISOString()});keys.set(row.session_id,row.organization_id)}save(d);for(const [sessionId,organizationId] of keys){try{await maybeAutoOffer(d,sessionId,organizationId)}catch(e){console.error('Waitlist promotion maintenance failed:',e.message)}}}
function sessionView(d,s){for(const w of d.waitlist||[])if(w.session_id===s.id&&w.status==='offered'&&w.offer_expires_at&&new Date(w.offer_expires_at)<=new Date())w.status='expired';const regs=d.registrations.filter(r=>r.session_id===s.id&&r.status==='enrolled');const wl=d.waitlist.filter(w=>w.session_id===s.id&&['waiting','offered'].includes(w.status)).sort((a,b)=>a.created_at.localeCompare(b.created_at));return {...s,enrolled:regs.length,available:Math.max(0,s.capacity-regs.length-wl.filter(w=>w.status==='offered').length),waitlist_count:wl.length};}
