 if(req.method==='GET'&&u.pathname==='/health'){const issues=[],now=Date.now();for(const s of d.sessions){const enrolled=d.registrations.filter(r=>r.session_id===s.id&&r.status==='enrolled').length,reserved=(d.waitlist||[]).filter(w=>w.session_id===s.id&&w.status==='offered'&&(!w.offer_expires_at||new Date(w.offer_expires_at).getTime()>now)).length,committed=enrolled+reserved;if(committed>Number(s.capacity))issues.push({type:'over_capacity_commitment',session_id:s.id,enrolled,reserved,capacity:s.capacity})}const duplicateRegs=new Set(),seenRegs=new Set();for(const r of d.registrations.filter(x=>x.status==='enrolled')){const k=r.session_id+'|'+r.participant_id;if(seenRegs.has(k))duplicateRegs.add(k);seenRegs.add(k);if(!d.sessions.some(s=>s.id===r.session_id)||!d.participants.some(p=>p.id===r.participant_id))issues.push({type:'orphan_registration',registration_id:r.id})}if(duplicateRegs.size)issues.push({type:'duplicate_enrollment',count:duplicateRegs.size});const seenWait=new Set(),duplicateWait=new Set();for(const w of (d.waitlist||[]).filter(x=>['waiting','offered'].includes(x.status))){const k=w.session_id+'|'+w.participant_id;if(seenWait.has(k))duplicateWait.add(k);seenWait.add(k);if(!d.sessions.some(s=>s.id===w.session_id)||!d.participants.some(p=>p.id===w.participant_id))issues.push({type:'orphan_waitlist',waitlist_id:w.id})}if(duplicateWait.size)issues.push({type:'duplicate_active_waitlist',count:duplicateWait.size});for(const p of d.participants)if(!d.families.some(f=>f.id===p.family_id))issues.push({type:'orphan_participant',participant_id:p.id});for(const s of d.sessions)if(!d.programs.some(p=>p.id===s.program_id))issues.push({type:'orphan_session',session_id:s.id});let db=null;try{db=await database.check();if(!db.enabled)issues.push({type:'database_disabled'})}catch(e){issues.push({type:'database_unreachable',message:e.message})}if(!databaseStatus.ready)issues.push({type:'database_not_ready',message:databaseStatus.error||null});if(!process.env.SESSION_SECRET)issues.push({type:'session_secret_missing'});return json(res,issues.length?503:200,{ok:issues.length===0,service:'rosterllama',database:{enabled:!!db?.enabled,ready:databaseStatus.ready},checks:{sessions:d.sessions.length,registrations:d.registrations.length,waitlist:(d.waitlist||[]).length,issues}});}
